INSERT INTO workflow_templates (slug,title,summary,tool_slug,method_code,problem_type,difficulty,estimated_minutes,input_payload,status,sort_order,published_at) VALUES
('regression-study-hours-score', 'رابطهٔ ساعت مطالعه و نمرهٔ آزمون', 'با دادهٔ آموزشی کوچک، جهت و شدت رابطهٔ دو متغیر را در یک پروژهٔ رگرسیون بررسی کنید.', 'statlab-analyzer', 'regression', 'simple_regression', 'beginner', 15, '{"problem_statement":"آیا افزایش ساعت مطالعه با نمرهٔ آزمون رابطه دارد؟ داده‌ها ساختگی و صرفاً آموزشی‌اند.","preview":{"columns":["دانشجو","ساعت مطالعه","نمره"],"rows":[["الف",2,11],["ب",3,13],["پ",4,14],["ت",5,16],["ث",6,17],["ج",7,19]]},"steps":["متغیر پاسخ و پیش‌بین را مشخص کنید.","رابطه و شیب خط برازش‌شده را بررسی کنید.","محدودیت حجم نمونه و دادهٔ آموزشی را در تفسیر بنویسید."],"interpretation_note":"این داده‌ها ساختگی‌اند و برای نتیجه‌گیری دربارهٔ دانشجویان واقعی مناسب نیستند."}', 'published', 50, CURRENT_TIMESTAMP),
('process-cycle-time-compare', 'مقایسهٔ زمان چرخه در دو شیفت', 'زمان‌های چرخهٔ دو شیفت را به‌صورت نمونه در پروژهٔ آماری ثبت و برای مقایسه آماده کنید.', 'statlab-analyzer', 'two_sample_t', 'two_sample_comparison', 'intermediate', 20, '{"problem_statement":"آیا زمان چرخهٔ ثبت‌شده در دو شیفت تفاوتی نشان می‌دهد؟","preview":{"columns":["مشاهده","شیفت الف (دقیقه)","شیفت ب (دقیقه)"],"rows":[[1,18,20],[2,17,22],[3,19,21],[4,20,19],[5,18,23],[6,16,20]]},"steps":["نوع مقایسه و استقلال مشاهدات را بررسی کنید.","توزیع داده و آمار توصیفی هر شیفت را ببینید.","پیش از نتیجه‌گیری، فرض‌های آزمون مناسب را ارزیابی کنید."],"interpretation_note":"به‌دلیل کوچک بودن نمونه، این مثال فقط برای تمرین جریان تحلیل است."}', 'published', 51, CURRENT_TIMESTAMP),
('inventory-demand-description', 'خلاصه‌سازی تقاضای هفتگی انبار', 'با دادهٔ تقاضای هفت دوره، پراکندگی و سطح معمول مصرف را مرور کنید.', 'statlab-analyzer', 'summary_stats', 'descriptive_statistics', 'beginner', 10, '{"problem_statement":"مسئول انبار می‌خواهد سطح و نوسان تقاضای هفتگی یک قلم را بشناسد.","preview":{"columns":["هفته","تقاضا (واحد)"],"rows":[[1,42],[2,38],[3,51],[4,47],[5,45],[6,58],[7,49]]},"steps":["میانگین و میانه را مقایسه کنید.","دامنه و انحراف معیار را برای سنجش نوسان بررسی کنید.","دورهٔ اوج را شناسایی و دلیل عملی احتمالی را مطرح کنید."],"interpretation_note":"برای سیاست سفارش‌دهی، فصل‌پذیری و زمان تأمین نیز باید بررسی شود."}', 'published', 52, CURRENT_TIMESTAMP),
('service-defect-rate-test', 'بررسی نرخ نقص خدمت', 'دادهٔ درصد نقص چند دوره را برای تمرین خلاصه‌سازی و بررسی روند وارد کنید.', 'statlab-analyzer', 'summary_stats', 'process_monitoring', 'intermediate', 15, '{"problem_statement":"تیم بهبود می‌خواهد نرخ نقص گزارش‌شده در دوره‌های متوالی را مرور کند.","preview":{"columns":["دوره","نرخ نقص (درصد)"],"rows":[[1,4.2],[2,3.8],[3,4.5],[4,3.4],[5,3.1],[6,3.7],[7,2.9]]},"steps":["روند زمانی مقادیر را ترسیم کنید.","تغییر سطح و پراکندگی را بررسی کنید.","برای پایش رسمی، حجم نمونه و نوع نمودار کنترل را تعیین کنید."],"interpretation_note":"این جدول خلاصهٔ آموزشی است و جایگزین دادهٔ شمارشی خام برای نمودار کنترل نیست."}', 'published', 53, CURRENT_TIMESTAMP),
('course-selection-topsis', 'انتخاب درس اختیاری با TOPSIS', 'سه درس را با معیارهای علاقه، کاربرد، بار زمانی و تناسب پژوهشی رتبه‌بندی کنید.', 'mcdm-analyzer', 'TOPSIS', 'course_selection', 'beginner', 20, '{"problem_statement":"دانشجو میان سه درس اختیاری با چند معیار قابل‌مقایسه تصمیم می‌گیرد.","preview":{"columns":["گزینه","علاقه (از 10)","کاربرد (از 10)","بار زمانی (ساعت)","تناسب پژوهشی (از 10)"],"rows":[["درس الف",8,7,3,9],["درس ب",7,9,5,8],["درس پ",9,6,2,7]]},"steps":["جهت معیارها را تعیین کنید؛ بار زمانی معیار هزینه است.","اهمیت معیارها را با مشارکت تصمیم‌گیرنده وزن‌دهی کنید.","رتبهٔ TOPSIS را همراه تحلیل حساسیت گزارش کنید."],"interpretation_note":"امتیازها فرضی‌اند؛ رتبه به وزن‌های انتخاب‌شده حساس است."}', 'published', 54, CURRENT_TIMESTAMP),
('maintenance-strategy-saw', 'مقایسهٔ راهبردهای نگهداری با SAW', 'راهبردهای واکنشی، پیشگیرانه و پیش‌بینانه را روی هزینه، ریسک و دسترس‌پذیری مقایسه کنید.', 'mcdm-analyzer', 'SAW', 'maintenance_strategy', 'intermediate', 25, '{"problem_statement":"تیم نگهداری برای یک تجهیز آموزشی سه راهبرد را با معیارهای متعارض می‌سنجد.","preview":{"columns":["راهبرد","هزینهٔ سالانه (واحد فرضی)","دسترس‌پذیری (از 10)","ریسک توقف (از 10)"],"rows":[["واکنشی",4,5,8],["پیشگیرانه",7,8,4],["پیش‌بینانه",8,9,3]]},"steps":["هزینه و ریسک را به‌عنوان معیارهای هزینه‌ای مشخص کنید.","مقیاس معیارها را هم‌جهت و وزن‌ها را نرمال کنید.","امتیاز SAW و حساسیت نتیجه به وزن‌ها را بسنجید."],"interpretation_note":"اعداد فرضی‌اند و مقیاس هزینه باید پیش از مقایسه واقعی هم‌مقیاس شود."}', 'published', 55, CURRENT_TIMESTAMP),
('supplier-risk-vikor', 'توازن هزینه و ریسک تأمین‌کننده با VIKOR', 'گزینه‌های تأمین را با معیارهای هزینه، کیفیت و ریسک تحویل تحلیل سازشی کنید.', 'mcdm-analyzer', 'VIKOR', 'supplier_risk', 'advanced', 30, '{"problem_statement":"واحد خرید به دنبال گزینه‌ای سازشی میان هزینه، کیفیت و اطمینان تحویل است.","preview":{"columns":["گزینه","هزینه (واحد فرضی)","کیفیت (از 10)","اطمینان تحویل (از 10)"],"rows":[["تأمین‌کننده الف",85,8,7],["تأمین‌کننده ب",72,7,8],["تأمین‌کننده پ",91,9,9]]},"steps":["جهت معیارها و مقیاس‌ها را کنترل کنید.","وزن‌های معیار را مستند کنید.","شرط مزیت قابل‌قبول و پایداری رتبه در VIKOR را تفسیر کنید."],"interpretation_note":"انتخاب نهایی به وزن‌ها و ضریب توافق وابسته است؛ نتیجه را با تصمیم‌گیرندگان بازبینی کنید."}', 'published', 56, CURRENT_TIMESTAMP),
('project-prioritization-ahp', 'اولویت‌بندی پروژه‌های بهبود با AHP', 'یک ماتریس امتیاز گزینه‌ها برای تصمیم‌گیری چندمعیاره بسازید و اهمیت معیارها را شفاف کنید.', 'mcdm-analyzer', 'AHP', 'improvement_prioritization', 'intermediate', 25, '{"problem_statement":"تیم بهبود باید میان سه پروژه با منابع محدود اولویت انتخاب کند.","preview":{"columns":["پروژه","اثر (از 10)","هزینه (واحد فرضی)","زمان اجرا (هفته)"],"rows":[["کاهش دوباره‌کاری",9,7,6],["بهبود چیدمان",7,5,4],["دیجیتالی‌سازی",8,9,8]]},"steps":["ساختار هدف، معیار و گزینه‌ها را تنظیم کنید.","مقایسهٔ زوجی معیارها و گزینه‌ها را تکمیل کنید.","نسبت سازگاری را ارزیابی و اولویت‌ها را تحلیل کنید."],"interpretation_note":"امتیازهای جدول فقط پیش‌نمایش هستند؛ قضاوت زوجی باید در فرایند AHP تکمیل شود."}', 'published', 57, CURRENT_TIMESTAMP)
